  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "In humans, [123/124/131I]AM281 readily permeates the BBB and enables CB1 quantification, providing direct evidence that the closest structural analog has meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Ex vivo autoradiography in rats after intravenous AM281 injection shows high brain radioactivity in CB1-rich regions, confirming brain uptake after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A less similar analog, MJ15, showed lowered brain distribution in mice, indicating that some close analogs can lose BBB penetration and tempering the positive evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogs (AM281) show direct human BBB permeation and rat brain uptake, and several additional analogs show favorable brain penetration. Although some intermediate-similarity analogs have low brain distribution, the strongest and most similar evidence supports meaningful CNS access.",
  "evidence_gaps": [
    "No direct query-specific in vivo brain exposure data; prediction relies on analog transfer.",
    "Negative analogs at intermediate similarity indicate that small structural changes can reduce BBB penetration, adding uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

